using System.Reflection;
using System.Runtime.InteropServices;
using ProtoBuf;
using WolfConquer.Core.Networking;
using WolfConquer.Core.World;

namespace WolfConquer.Tests;

// Corrected source ONLY: the old unchecked writer can overwrite unmanaged memory
// for the large-name controls below. Never execute those cases as an old baseline.
[Collection("NativeItemCounterSourcePrerequisite")]
public sealed class CorrectedOnlyNativeTradeInfoSafetyTests
{
    // Independent retained twenty-required-field wire golden from the native
    // TeleportLifecycle contract test, not generated by the writer under test.
    private static byte[] DefaultGolden => Convert.FromHexString(
        "32005C0908001000180022014128003000380040004800500058006000680070007800800100880100900100980100A00100");

    [Fact]
    public Task IndependentFiftyByteGoldenRetainsRequiredDefaultsHeaderAndReturnedCursor() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        using var packet = new LegacyNativeMsgTrade.TradeInfo { Name = "A" }.ToArray();
        Assert.Equal(DefaultGolden, Bytes(packet));
        Assert.Equal(50, packet.Size); Assert.Equal(0, packet.Position);
        Assert.True(packet.Capacity >= packet.Size);
    });

    [Fact]
    public Task IndependentUtf8RelationsAndNegativeInt64GoldenRetainsAllTwentyFields() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        var input = new LegacyNativeMsgTrade.TradeInfo
        {
            un1 = false, un2 = 2, Sender = 1, Name = "é", Receiver = 2, Level = 3, BattlePower = 4,
            un8 = 8, un9 = 9, Spouse = true, Friend = true, TradePartner = true, Mentor = true,
            Apprentice = true, Teammate = true, GuildMember = true, Enemy = true, un18 = 18, un19 = 19, un20 = -1,
        };
        using var packet = input.ToArray();
        var expected = Convert.FromHexString(
            "3C005C090800100218012202C3A928023003380440084809500158016001680170017801800101880101900112980113A001FFFFFFFFFFFFFFFFFF01");
        Assert.Equal(expected, Bytes(packet)); Assert.Equal(0, packet.Position);
    });

    [Theory]
    [InlineData("TQServer", "5451536572766572")]
    [InlineData("é1234567", "C3A9313233343536")]
    public Task SealRetainsNativeFirstEightUtf8BytesAndHeaderExcludesSeal(string captured, string sealHex) => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope(captured);
        using var packet = new LegacyNativeMsgTrade.TradeInfo { Name = "A" }.ToArray();
        var expected = DefaultGolden.Concat(Convert.FromHexString(sealHex)).ToArray();
        LegacyNativePacket.SealString = "Changed!";
        Assert.Equal(expected, Bytes(packet));
        Assert.Equal(58, packet.Size); Assert.Equal((ushort)50, BitConverter.ToUInt16(Bytes(packet), 0));
        Assert.Equal(0, packet.Position);
    });

    [Fact]
    public Task EmptyNameIsRequiredPresentAndNullNameRefusesWithoutPoisoningOtherResults() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        using var prior = new LegacyNativeMsgTrade.TradeInfo { Name = "A" }.ToArray();
        using var empty = new LegacyNativeMsgTrade.TradeInfo { Name = "" }.ToArray();
        Assert.Equal(49, empty.Size);
        Assert.Equal(new byte[] { 0x22, 0 }, Bytes(empty).AsSpan(10, 2).ToArray());
        var invalid = new LegacyNativeMsgTrade.TradeInfo { Name = null, Sender = 17 };
        Assert.Equal("Name", Assert.Throws<ArgumentNullException>(() => invalid.ToArray()).ParamName);
        Assert.Null(invalid.Name); Assert.Equal(17U, invalid.Sender);
        Assert.Equal(DefaultGolden, Bytes(prior));
        invalid.Name = "A"; invalid.Sender = 0;
        using var retry = invalid.ToArray(); Assert.Equal(DefaultGolden, Bytes(retry));
    });

    [Fact]
    public Task ResultsHaveIndependentRealStorageAndCallerDisposalDoesNotInvalidateAnother() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        var input = new LegacyNativeMsgTrade.TradeInfo { Name = "A" };
        using var first = input.ToArray(); using var second = input.ToArray();
        Assert.NotSame(first, second); Assert.NotEqual(Address(first), Address(second));
        input.Name = "Changed"; input.Friend = true; input.un20 = long.MinValue;
        first.Seek(4); first.Write((byte)0xa5);
        Assert.Equal(DefaultGolden, Bytes(second));
        first.Dispose(); Assert.Equal((nint)0, Address(first));
        Assert.Equal(DefaultGolden, Bytes(second)); Assert.Equal(0, second.Position);
    });

    [Fact]
    public Task RealRentalReuseOnlyResetsItsOwnCursorAndCannotAliasTheOwnedTradeResult() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        using var result = new LegacyNativeMsgTrade.TradeInfo { Name = "A" }.ToArray();
        using var rental = new LegacyNativeRecycledPacket();
        var borrowed = rental.GetStream();
        try
        {
            Assert.NotSame(result, borrowed); Assert.NotEqual(Address(result), Address(borrowed));
            borrowed.InitWriter(); borrowed.Write(0xaabbccddU); borrowed.Finalize(2119);
            rental.Dispose(); // Genuine current Reuse only seeks to0: no fake accepting pool.
            Assert.Equal(0, borrowed.Position); Assert.NotEqual((nint)0, Address(borrowed));
            borrowed.InitWriter(); borrowed.Write(0x11223344U);
            borrowed.Dispose();
            Assert.Equal(DefaultGolden, Bytes(result)); Assert.Equal(0, result.Position);
        }
        finally { borrowed.Dispose(); }
    });

    [Theory]
    [InlineData(false)] [InlineData(true)]
    public Task ExactAsciiEnvelopeFitsAndTheNextByteRefusesWithoutTouchingEarlierPackets(bool sealedFrame) => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope(sealedFrame ? "TQServer" : null);
        var sealBytes = sealedFrame ? 8 : 0;
        // Independent schema count: for this two-byte name-length prefix the
        // default frame is50+UTF8-name-bytes, plus captured8-byte seal if present.
        var nameBytes = LegacyNativePacket.MAX_SIZE - 50 - sealBytes;
        var input = new LegacyNativeMsgTrade.TradeInfo { Name = new string('A', nameBytes) };
        using var boundary = input.ToArray(); var preserved = Bytes(boundary);
        Assert.Equal(LegacyNativePacket.MAX_SIZE, boundary.Size);
        Assert.Equal((ushort)(LegacyNativePacket.MAX_SIZE - sealBytes), BitConverter.ToUInt16(preserved, 0));
        Assert.Equal((ushort)2396, BitConverter.ToUInt16(preserved, 2)); Assert.Equal(0, boundary.Position);
        input.Name += "A";
        Assert.Throws<InvalidOperationException>(() => input.ToArray());
        Assert.Equal(nameBytes + 1, input.Name.Length); Assert.Equal(preserved, Bytes(boundary));
    });

    [Theory]
    [InlineData(false)] [InlineData(true)]
    public Task MultibyteNameUsesUtf8ByteEnvelopeRatherThanAnArbitraryCharacterLimit(bool sealedFrame) => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope(sealedFrame ? "TQServer" : null);
        var nameBytes = LegacyNativePacket.MAX_SIZE - 50 - (sealedFrame ? 8 : 0);
        var input = new LegacyNativeMsgTrade.TradeInfo { Name = new string('é', nameBytes / 2) };
        Assert.Equal(nameBytes, System.Text.Encoding.UTF8.GetByteCount(input.Name));
        using var boundary = input.ToArray(); Assert.Equal(LegacyNativePacket.MAX_SIZE, boundary.Size);
        input.Name += "é"; Assert.Throws<InvalidOperationException>(() => input.ToArray());
    });

    [Fact]
    public Task FullSerializedScalarOverheadCountsAndLargeNameRefusalLeavesInputAndPriorPacketIntact() => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        using var prior = new LegacyNativeMsgTrade.TradeInfo { Name = "A" }.ToArray();
        var fitsNameAlone = new LegacyNativeMsgTrade.TradeInfo
            { Name = new string('A', LegacyNativePacket.MAX_SIZE - 50), Sender = uint.MaxValue };
        Assert.Throws<InvalidOperationException>(() => fitsNameAlone.ToArray());
        Assert.Equal(uint.MaxValue, fitsNameAlone.Sender);
        var hugeName = new string('雪', LegacyNativePacket.MAX_SIZE);
        var oversized = new LegacyNativeMsgTrade.TradeInfo { Name = hugeName, Friend = true };
        Assert.Throws<InvalidOperationException>(() => oversized.ToArray());
        Assert.Same(hugeName, oversized.Name); Assert.True(oversized.Friend);
        Assert.Equal(DefaultGolden, Bytes(prior));
    });

    [Theory]
    [InlineData(long.MinValue)] [InlineData(-1L)] [InlineData(long.MaxValue)]
    public Task FullWidthScalarsRemainValidOpaqueValuesRatherThanNewAdmissionRules(long unknown) => NativePacketTestThread.Run(() =>
    {
        using var seal = new SealScope();
        var input = new LegacyNativeMsgTrade.TradeInfo
        {
            Name = "A", un1 = true, un2 = uint.MaxValue, Sender = uint.MaxValue, Receiver = uint.MaxValue,
            Level = uint.MaxValue, BattlePower = uint.MaxValue, un8 = uint.MaxValue, un9 = uint.MaxValue,
            un18 = uint.MaxValue, un19 = uint.MaxValue, un20 = unknown,
        };
        using var packet = input.ToArray(); var bytes = Bytes(packet);
        using var body = new MemoryStream(bytes, 4, bytes.Length - 4);
        var decoded = Serializer.Deserialize<LegacyNativeMsgTrade.TradeInfo>(body);
        Assert.Equal(uint.MaxValue, decoded.Sender); Assert.Equal(uint.MaxValue, decoded.Level);
        Assert.Equal(uint.MaxValue, decoded.BattlePower); Assert.Equal(uint.MaxValue, decoded.un19);
        Assert.Equal(unknown, decoded.un20); Assert.True(decoded.un1);
    });

    private static unsafe nint Address(LegacyNativePacket packet) => (nint)packet.Memory;
    private static unsafe byte[] Bytes(LegacyNativePacket packet)
    {
        Assert.True(packet.Size <= packet.Capacity);
        var bytes = new byte[packet.Size]; Marshal.Copy((nint)packet.Memory, bytes, 0, bytes.Length); return bytes;
    }
    private sealed class SealScope : IDisposable
    {
        private static readonly FieldInfo Field = typeof(LegacyNativePacket).GetField("seal", BindingFlags.NonPublic | BindingFlags.Static)!;
        private readonly object? prior = Field.GetValue(null);
        internal SealScope(string? seal = null)
        {
            // Restore the real no-seal initial state or use its legitimate8-character setter.
            if (seal is null) Field.SetValue(null, null);
            else LegacyNativePacket.SealString = seal;
        }
        public void Dispose() => Field.SetValue(null, prior);
    }
}
